def transform(grid):
    out = [row[:] for row in grid]
    baseline = next((r for r, row in enumerate(grid) if any(v != 0 for v in row)), None)
    if baseline is None:
        return out
    for c, value in enumerate(grid[baseline]):
        if value in (2, 8):
            top = max(0, baseline - 4)
            out[top][c] = value
            for r in range(top + 1, baseline):
                out[r][c] = 1
    return out

